package com.primehr.rsp.evaluation.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="rsp_hrmpsb_resolution") public class HrmpsbResolution extends RspAuditedEntity{
 public enum Recommendation{ENDORSED_FOR_SELECTION_DECISION,NOT_ENDORSED,DEFERRED}public enum Method{CONSENSUS,VOTE}
 @Column(name="meeting_id",nullable=false,length=36)private String meetingId;@Column(name="candidate_id",nullable=false,length=36)private String candidateId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=40)private Recommendation recommendation;@Column(nullable=false,length=3000)private String reason;@Enumerated(EnumType.STRING)@Column(name="decision_method",nullable=false,length=30)private Method method;@Column(name="votes_for")private Integer votesFor;@Column(name="votes_against")private Integer votesAgainst;private Integer abstentions;@Column(name="recorded_by",nullable=false,length=100)private String recordedBy;@Column(name="recorded_at",nullable=false)private Instant recordedAt;
 protected HrmpsbResolution(){}public HrmpsbResolution(String agency,String meeting,String candidate,Recommendation recommendation,String reason,Method method,Integer forVotes,Integer against,Integer abstentions,String actor,Instant at){super(agency);meetingId=requiredText(meeting,"meetingId");candidateId=requiredText(candidate,"candidateId");this.recommendation=Objects.requireNonNull(recommendation);this.reason=requiredText(reason,"reason");this.method=Objects.requireNonNull(method);if(method==Method.VOTE&&(forVotes==null||against==null||abstentions==null))throw new IllegalArgumentException("Vote counts are required for a vote");for(Integer value:List.of(forVotes==null?0:forVotes,against==null?0:against,abstentions==null?0:abstentions))if(value<0)throw new IllegalArgumentException("Vote counts cannot be negative");votesFor=forVotes;votesAgainst=against;this.abstentions=abstentions;recordedBy=requiredText(actor,"actor");recordedAt=Objects.requireNonNull(at);}
 public String getMeetingId(){return meetingId;}public String getCandidateId(){return candidateId;}public Recommendation getRecommendation(){return recommendation;}public String getReason(){return reason;}public Method getMethod(){return method;}public Integer getVotesFor(){return votesFor;}public Integer getVotesAgainst(){return votesAgainst;}public Integer getAbstentions(){return abstentions;}
}
